            if(dolby){var template=Path.Combine(directory,"reconstruct-config-"+index+".mp4");await RunAsync(ffmpeg,["-y","-v","error","-i",input,"-map","0:v:0","-c","copy","-strict","unofficial",template],ct,rejectDiagnostics:true).ConfigureAwait(false);await Mp4DolbyConfiguration.CopyAsync(template,path,ct,width,policy.TransitionHeight).ConfigureAwait(false);}
