    private static async Task RenderAffineAsync(string ffmpeg,string input,string output,ProbedStream source,HdrAffineCanvas canvas,IReadOnlyList<HdrTimedFrame> frames,IReadOnlyList<int> selected,TransitionHdrMetadata metadata,CancellationToken ct)
