        while(await decoder.ReadAsync(frame,ct).ConfigureAwait(false)){if(index>=frameCount)throw new InvalidDataException("Affine decoder produced extra pictures.");if(at<selected.Count&&selected[at]==index){ct.ThrowIfCancellationRequested();HdrSourceTransfer.Create(source.ColorTransfer,frames[index].Metadata.Static)?.Convert(frame,source.Width,source.Height,ct);canvas.Render(frame,rendered,ct);do{await encoder.Stream.WriteAsync(rendered,ct).ConfigureAwait(false);at++;}while(at<selected.Count&&selected[at]==index);}index++;}if(index!=frameCount||at!=selected.Count)throw new InvalidDataException("Affine picture selection is incomplete.");await decoder.FinishAsync(ct).ConfigureAwait(false);await encoder.FinishAsync(ct).ConfigureAwait(false);
    }
    private static async Task RegeneratePixelHistogramsAsync(string ffmpeg,string input,int width,int height,IReadOnlyList<HdrTimedFrame> frames,CancellationToken ct)
    {
        var pixels=checked(width*height);var bytes=new byte[checked(pixels*12)];await using var decoder=new RawVideoPipe(ffmpeg,["-v","error","-xerror","-threads","1","-filter_threads","1","-protocol_whitelist","file,pipe","-f","mov","-enable_drefs","0","-use_absolute_path","0","-i",input,"-map","0:v:0","-vf","zscale=transfer=linear:primaries=2020:matrix=gbr:range=full:npl=10000,format=gbrpf32le","-fps_mode","passthrough","-pix_fmt","gbrpf32le","-f","rawvideo","pipe:1"],false,ct);var index=0;while(await decoder.ReadAsync(bytes,ct).ConfigureAwait(false)){if(index>=frames.Count)throw new InvalidDataException("Histogram decoder produced extra pictures.");if(frames[index].PlusPayload is { } plus){var windows=HdrPlusHistogram.Windows(plus,width,height);var statistics=new List<HdrPixelStatistics>();foreach(var window in windows)statistics.Add(HdrPixelHistogram.Measure(bytes,width,height,window,ct));frames[index].PlusPayload=HdrPlusHistogram.Regenerate(plus,statistics);}index++;}await decoder.FinishAsync(ct).ConfigureAwait(false);if(index!=frames.Count)throw new InvalidDataException("Histogram decoder lost pictures: "+index+" of "+frames.Count+".");
